/* Region tabs and the centred card for the brands carousel.
   The platform `carousel` behaviour already provides the rail, arrows and
   keyboard support. What it cannot express is (a) tabs that choose which
   brands the rail holds and (b) emphasising whichever card is centred, so this
   script adds those two things on top and nothing else. Without it the rail is
   an ordinary scrolling list of every brand. */
(function () {
  document.querySelectorAll('[data-bz-section="region-brands"]').forEach(function (root) {
    var rail = root.querySelector('[data-bz-node="rb-rail"]');
    if (!rail) return;
    var slides = [].slice.call(rail.querySelectorAll('[data-bz-part="slide"]'));
    var tabs = [].slice.call(root.querySelectorAll('[data-bz-node^="rb-tab-btn"] a'));
    if (!slides.length) return;

    function regionsOf(slide) {
      var n = slide.querySelector('[data-bz-node^="rb-regions"]');
      return (n ? n.textContent : '').toLowerCase().split(/[\s,]+/).filter(Boolean);
    }
    function keyOf(tab) { return (tab.getAttribute('href') || '').replace(/^#/, '').toLowerCase(); }
    function visible() { return slides.filter(function (s) { return !s.hidden; }); }

    var raf = 0;
    function mark() {
      raf = 0;
      var box = rail.getBoundingClientRect();
      var mid = box.left + box.width / 2, best = null, bestD = Infinity;
      visible().forEach(function (s) {
        var r = s.getBoundingClientRect();
        var d = Math.abs(r.left + r.width / 2 - mid);
        if (d < bestD) { best = s; bestD = d; }
      });
      slides.forEach(function (s) { s.classList.toggle('is-center', s === best); });
    }
    function queue() { if (!raf) raf = requestAnimationFrame(mark); }

    function centre(slide, smooth) {
      if (!slide) return;
      // Centres are compared in viewport space so the card's own scale
      // transform (which keeps its centre fixed) cannot throw the maths off.
      var s = slide.getBoundingClientRect(), r = rail.getBoundingClientRect();
      var delta = (s.left + s.width / 2) - (r.left + r.width / 2);
      rail.scrollTo({ left: rail.scrollLeft + delta, behavior: smooth ? 'smooth' : 'auto' });
    }

    function select(key, smooth) {
      tabs.forEach(function (t) {
        var on = keyOf(t) === key;
        t.classList.toggle('is-active', on);
        t.setAttribute('aria-pressed', String(on));
      });
      slides.forEach(function (s) { s.hidden = key ? regionsOf(s).indexOf(key) < 0 : false; });
      var shown = visible();
      centre(shown[Math.floor((shown.length - 1) / 2)], smooth);
      queue();
    }

    tabs.forEach(function (t) {
      t.addEventListener('click', function (e) { e.preventDefault(); select(keyOf(t), true); });
    });
    slides.forEach(function (s) {
      s.addEventListener('click', function (e) {
        if (!s.classList.contains('is-center') && !e.target.closest('a')) centre(s, true);
      });
    });
    rail.addEventListener('scroll', queue, { passive: true });
    window.addEventListener('resize', queue);

    rail.classList.add('is-staged');
    var first = tabs[0] ? keyOf(tabs[0]) : '';
    select(first, false);
    // Fonts and images shift layout after first paint; re-centre once settled.
    window.addEventListener('load', function () {
      var shown = visible();
      centre(shown[Math.floor((shown.length - 1) / 2)], false);
      queue();
    });
  });
})();
